type Product={id:number;name:string;category:string;material:string;cost:number;price:number;stock:number;imageUrl?:string}; type Client={id:number;name:string;phone:string;email:string;birthday:string;preferences:string}; type Sale={id:number;date:string;productId:number;clientId:number;amount:number;payment:string;discount:number}; type Cash={id:number;date:string;type:"Entrada"|"Saída";category:string;description:string;amount:number}; type Promo={id:number;name:string;type:string;value:number;code:string;ends:string;active:boolean;uses:number};
const ago=(n:number)=>{const d=new Date();d.setDate(d.getDate()-n);return d.toISOString().slice(0,10)}; const br=(d:string)=>new Date(d+"T12:00:00").toLocaleDateString("pt-BR"); const money=(n:number)=>n.toLocaleString("pt-BR",{style:"currency",currency:"BRL"}); const initials=(n:string)=>n.split(" ").slice(0,2).map(x=>x[0]).join("").toUpperCase(); const uploadProductImage=async(ownerId:string,productId:number,file:File)=>{if(!supabase)throw new Error("Supabase indisponível");if(!["image/jpeg","image/png","image/webp","image/avif"].includes(file.type))throw new Error("Formato de imagem não permitido");if(file.size>5*1024*1024)throw new Error("A imagem deve ter no máximo 5 MB");const ext=file.name.split(".").pop()?.toLowerCase()||"jpg";const objectPath=ownerId+"/"+productId+"-"+Date.now()+"."+ext;const {error}=await supabase.storage.from("product-images").upload(objectPath,file,{contentType:file.type,upsert:false});if(error)throw error;return supabase.storage.from("product-images").getPublicUrl(objectPath).data.publicUrl};
const products0:Product[]=[{id:1,name:"Anel Solitário Aurora",category:"Joia",material:"Ouro 18k",cost:620,price:1290,stock:4},{id:2,name:"Colar Gota Serena",category:"Semi-joia",material:"Prata 925",cost:118,price:289,stock:8},{id:3,name:"Brinco Pérola Luna",category:"Joia",material:"Ouro 18k",cost:410,price:890,stock:2},{id:4,name:"Pulseira Luz",category:"Semi-joia",material:"Banho rosé",cost:74,price:189,stock:12},{id:5,name:"Ear Cuff Rosé",category:"Acessório",material:"Banho rosé",cost:28,price:89,stock:3},{id:6,name:"Aliança Essenza",category:"Joia",material:"Ouro 18k",cost:780,price:1790,stock:5},{id:7,name:"Mix de Anéis Dourado",category:"Semi-joia",material:"Banho 18k",cost:95,price:249,stock:7}];
